    beats = {
        { id = "wall", at = 15, title = "Over the wall",
            text = "I began as a piece of root with a fan of leaves, snapped off when a gardener split a crowded bed. There were too many of me, so over the wall I went, into the next garden. My first delivery was myself, by air." },
        { id = "beard", at = 40, title = "The first guest",
            text = "My first spring there, I opened a flower. A bee landed on my lower petal, walked up the beard as if reading a sign, and went straight in. I had a visitor before I had a name. I have loved visitors ever since." },
        { id = "name", at = 80, title = "The name",
            text = "A child crouched by me and told her grandfather I was a rainbow. He laughed and said yes, iris means rainbow, after the goddess who carried messages along one. From that day I have been trying to live up to the job." },
        { id = "divided", at = 140, title = "Divided",
            text = "I spread, as we do, and one summer I was lifted and split again. Pieces of me went to five gardens up and down the street. I have relatives everywhere and hear from none of them. A messenger with no news from home. Funny, that." },
        { id = "orris", at = 220, title = "Orris",
            text = "One piece of me, I heard later, was never planted. Somebody dried that root for years in a dark loft until the root smelled of violets, then ground the powder for a linen cupboard. Somewhere, a sister of mine scents somebody's sheets. I hope they sleep well." },
        { id = "bridge", at = 320, title = "The bridge",
            text = "My own piece was planted by a little footbridge over a stream. Every morning a postman crossed with a heavy bag, and every morning I envied that bag. All those letters, all that news, going to people who were waiting." },
        { id = "flood", at = 450, title = "The flood",
            text = "One wet spring the stream rose over the bank and took the bridge, and took me. I tumbled downstream in brown water for a long way. Bearded irises hate wet feet. I had never been wetter. I thought my route had come to an end." },
        { id = "sill", at = 600, title = "The windowsill",
            text = "Someone fished me out of the mud at a bend in the river and carried me home. They laid my root on a sunny windowsill for a week to dry, exactly as an iris likes. The first person I ever met who knew how I wanted to be treated. I never learned their name." },
        { id = "shallow", at = 800, title = "Planted shallow",
            text = "They planted me here with my root half out of the soil, warming in the sun, and went away. That spring I flowered harder than I ever had. I could not have told you why, then. Some news takes a flood to arrive." },
        { id = "post", at = 1050, title = "Post without a postman",
            text = "Then you came, sat beside me, and opened a book. No bag, no bridge, no postman, and yet you were plainly receiving news from very far away. I was jealous for a whole day. Then I simply asked you to tell me, and you did." },
        { id = "hands", at = 1400, title = "The hands",
            text = "{total} pages now, and I have heard about a great many of them. Sometimes I think of the hands that fished me from the river. They held my root the way you hold a book: carefully, as if something inside might be news. A messenger knows when to leave a letter sealed." },
        { id = "rainbow", at = 1800, title = "The rainbow",
            text = "The goddess walked the rainbow between the sky and the ground, carrying words for others. I have done the same, between the bees and the wall, between your books and this bed. Every messenger hopes for one letter of their own. Mine came. Mine is you, stopping each day to tell me what you read." },
    },
}
